function OverseaClubBossRecordNodeCell:__init()
    self.callBack = nil
end

function OverseaClubBossRecordNodeCell:__delete()
    self.callBack = nil
end

function OverseaClubBossRecordNodeCell:SetCallBack(callBack)
    self.callBack = callBack
end

function OverseaClubBossRecordNodeCell:Awake()
    if self.BtnCheck then
        SetButtonAction(self.BtnCheck,Bind(self,self.OnBtnCheckClick))
