function OverseaClubBossRecordNodeCell:RefreshShow(data)
    self.data = data
    local str = self:GetLocalizeByTime()
    CfUtils.FillText(self.TextDesc,str)
    self:RefreshHeadNode()

    local rectTrans = KTool.GetComponent(self.controller.gameObject, typeof(RectTransform))
    CS.UnityEngine.UI.LayoutRebuilder.ForceRebuildLayoutImmediate(rectTrans)
end

function OverseaClubBossRecordNodeCell:GetLocalizeByTime()
    local second = self.data.time
    local name = string.format("<color=#FFFFFF>%s</color>",self.data.playerName)
    local bossName = self:GetBossName()
    local d, h, m, s

    h = math.floor(second / 3600)

    d = math.floor(h / 24)
    --如果大于一天返回天数
    if d > 0 then
        return localize("_name_在_min_天前对_bossName_造成了_hurt_伤害", { _name_ = name,_min_ = d,_bossName_ = bossName,_hurt_ = self.data.hurt })
    end

    if h >= 1 then
        return localize("_name_在_min_小时前对_bossName_造成了_hurt_伤害", { _name_ = name,_min_ = h,_bossName_ = bossName,_hurt_ = self.data.hurt })
    end
    m = math.floor((second - 3600 * h) / 60)

    if m >= 1 then
        return localize("_name_在_min_分钟前对_bossName_造成了_hurt_伤害", { _name_ = name,_min_ = m,_bossName_ = bossName,_hurt_ = self.data.hurt })
    end

    s = math.floor(second - 3600 * h - 60 * m)

    return localize("_name_在_min_秒前对_bossName_造成了_hurt_伤害", { _name_ = name,_min_ = s,_bossName_ = bossName,_hurt_ = self.data.hurt })
end

function OverseaClubBossRecordNodeCell:GetBossName()
    local bossData = QuestConfMgr:GetInstance():GetAllQuestLineupVo(self.data.questId)
    local bossId
    local bossName = self.data.monsterName
    for i, v in pairs(bossData) do
        for k, j in pairs(v.wave1NpcType) do
            if tonumber(j) == Constants.RoleClass.Boss then
                bossId = v.wave1NpcId[k]
            end
        end
    end

    if not isNull(bossId) then
        local monster = CardConfMgr:GetInstance():GetBaseMonstVo(bossId)
        if not isNull(monster) then
            local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(monster.skinId)
            if not isNull(skinVo) then
                bossName = skinVo.name
            end
        end
    end
    return bossName
end

function OverseaClubBossRecordNodeCell:RefreshHeadNode()
    local scr = CfUtils.GetLuaScr(self.CommonPlayerHeadNode, "Game.Behaviours.CommonPlayerHeadNode")
    if isNotNull(scr) then
        scr:FreshAvatarFrame(self.data.avatar, self.data.avatarFrame)
    end
end

function OverseaClubBossRecordNodeCell:OnBtnCheckClick()
    if not isNull(self.callBack) then
        self.callBack(self.BtnCheck,self.data)
    end
end

function OverseaClubBossRecordNodeCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverseaClubBossRecordNodeCell